import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from "react";
import { jsx } from "react/jsx-runtime";
import { startAuthentication } from "@simplewebauthn/browser";

//#region src/NhostContext.ts
const NhostContext = createContext(null);

//#endregion
//#region src/NhostProvider.tsx
function NhostProvider({ children, nhostClient }) {
	const [user, setUser] = useState(null);
	const [session, setSession] = useState(null);
	const [isLoading, setIsLoading] = useState(true);
	const [isAuthenticated, setIsAuthenticated] = useState(false);
	const lastSessionKeyRef = useRef(null);
	const sessionKey = (currentSession) => currentSession ? `${currentSession.refreshTokenId}:${currentSession.accessToken}` : null;
	const applySession = useCallback((currentSession) => {
		const key = sessionKey(currentSession);
		if (key === lastSessionKeyRef.current) return;
		lastSessionKeyRef.current = key;
		setUser(currentSession?.user || null);
		setSession(currentSession);
		setIsAuthenticated(!!currentSession);
	}, []);
	useEffect(() => {
		const unsubscribe = nhostClient.sessionStorage.onChange(applySession);
		const onCrossTabStorage = (event) => {
			if (event.key !== "nhostSession") return;
			applySession(event.newValue ? JSON.parse(event.newValue) : null);
		};
		window.addEventListener("storage", onCrossTabStorage);
		return () => {
			unsubscribe();
			window.removeEventListener("storage", onCrossTabStorage);
		};
	}, [applySession, nhostClient]);
	useEffect(() => {
		async function initializeSession() {
			setIsLoading(true);
			const refreshTokenSearchParam = new URLSearchParams(window.location.search).get("refreshToken");
			if (refreshTokenSearchParam) {
				const removeRefreshToken = () => {
					const url = new URL(window.location.href);
					url.searchParams.delete("refreshToken");
					window.history.replaceState({}, "", url.href);
				};
				try {
					await nhostClient.auth.refreshToken({ refreshToken: refreshTokenSearchParam });
				} catch {
					removeRefreshToken();
					window.location.reload();
				} finally {
					removeRefreshToken();
				}
			}
			applySession(nhostClient.getUserSession());
			setIsLoading(false);
		}
		initializeSession();
	}, [nhostClient, applySession]);
	useEffect(() => {
		let refreshInFlight = null;
		let wasTabHidden = false;
		let wasWindowBlurred = false;
		const refreshSessionAfterIdle = () => {
			if (!nhostClient.getUserSession() || refreshInFlight) return;
			refreshInFlight = nhostClient.refreshSession().finally(() => {
				refreshInFlight = null;
			});
		};
		const onVisibilityChange = () => {
			if (document.hidden) {
				wasTabHidden = true;
				return;
			}
			if (wasTabHidden) {
				wasTabHidden = false;
				wasWindowBlurred = false;
				refreshSessionAfterIdle();
			}
		};
		const onWindowBlur = () => {
			wasWindowBlurred = true;
		};
		const onWindowFocus = () => {
			if (document.hidden || !wasWindowBlurred) return;
			wasWindowBlurred = false;
			refreshSessionAfterIdle();
		};
		document.addEventListener("visibilitychange", onVisibilityChange);
		window.addEventListener("blur", onWindowBlur);
		window.addEventListener("focus", onWindowFocus);
		return () => {
			document.removeEventListener("visibilitychange", onVisibilityChange);
			window.removeEventListener("blur", onWindowBlur);
			window.removeEventListener("focus", onWindowFocus);
		};
	}, [nhostClient]);
	const authContext = useMemo(() => {
		const signOut = async () => {
			if (!session?.refreshToken) return;
			setIsLoading(true);
			await nhostClient.auth.signOut({ refreshToken: session.refreshToken });
			applySession(null);
			setIsLoading(false);
		};
		const refreshSession = async () => {
			await nhostClient.refreshSession(0);
		};
		return {
			user,
			session,
			isAuthenticated,
			isLoading,
			nhost: nhostClient,
			userId: user?.id,
			signOut,
			refreshSession
		};
	}, [
		user,
		isLoading,
		nhostClient,
		session,
		isAuthenticated,
		applySession
	]);
	return /* @__PURE__ */ jsx(NhostContext.Provider, {
		value: authContext,
		children
	});
}

//#endregion
//#region src/hooks/useNhost.ts
const useNhost = () => {
	const context = useContext(NhostContext);
	if (!context) throw new Error("useAuth must be used within NhostProvider");
	return context;
};

//#endregion
//#region src/hooks/useShared.ts
function useShared({ onSuccess, onError }) {
	const { nhost } = useNhost();
	const [isLoading, setIsLoading] = useState(false);
	const [isSuccess, setIsSuccess] = useState(false);
	const [error, setError] = useState(null);
	const onSuccessRef = useRef(onSuccess);
	const onErrorRef = useRef(onError);
	useEffect(() => {
		onSuccessRef.current = onSuccess;
	}, [onSuccess]);
	useEffect(() => {
		onErrorRef.current = onError;
	}, [onError]);
	return {
		nhost,
		isLoading,
		isSuccess,
		error,
		callAsync: useCallback(async (cb, ...params) => {
			setIsLoading(true);
			setError(null);
			setIsSuccess(false);
			const firstParam = params[0];
			try {
				const result = await cb(...params);
				if (onSuccessRef.current) {
					const payload = {
						nhost,
						data: result,
						params: firstParam
					};
					await onSuccessRef.current(payload);
				}
				setIsSuccess(true);
				return result;
			} catch (e) {
				const fetchError = e;
				setError(fetchError);
				if (onErrorRef.current) {
					const payload = {
						nhost,
						error: fetchError,
						params: firstParam
					};
					await onErrorRef.current(payload);
				}
				return fetchError;
			} finally {
				setIsLoading(false);
			}
		}, [nhost])
	};
}

//#endregion
//#region src/hooks/useNhostAuth.ts
function useNhostAuth({ fn, onSuccess, onError }) {
	const { callAsync, isLoading, isSuccess, error, nhost } = useShared({
		onSuccess,
		onError
	});
	return {
		callAsync: useCallback(async (...params) => {
			const method = nhost.auth[fn];
			return callAsync((...p) => method(...p), ...params);
		}, [
			callAsync,
			nhost,
			fn
		]),
		isLoading,
		isSuccess,
		error
	};
}

//#endregion
//#region src/hooks/useNhostSecurity.ts
function useNhostSecurity() {
	const { nhost, user } = useNhost();
	const [securityKeys, setSecurityKeys] = useState([]);
	const [isLoading, setIsLoading] = useState(false);
	const isElevated = Boolean(nhost.getUserSession()?.decodedToken?.["https://hasura.io/jwt/claims"]?.["x-hasura-auth-elevated"]);
	const hasSecurityKeys = securityKeys.length > 0;
	const requiresElevation = !isElevated && hasSecurityKeys;
	const fetchSecurityKeys = useCallback(async () => {
		if (!user?.id) return;
		setIsLoading(true);
		try {
			const response = await nhost.graphql.request({
				query: `
          query securityKeys($userId: uuid!) {
            authUserSecurityKeys(where: { userId: { _eq: $userId } }) {
              id
              nickname
            }
          }
        `,
				variables: { userId: user.id }
			});
			if (response.body.data?.authUserSecurityKeys) setSecurityKeys(response.body.data.authUserSecurityKeys);
		} catch (error) {
			console.error("Failed to fetch security keys:", error);
		} finally {
			setIsLoading(false);
		}
	}, [user?.id, nhost]);
	const checkElevation = useCallback(async () => {
		if (!requiresElevation) return;
		try {
			const credential = await startAuthentication((await nhost.auth.elevateWebauthn())?.body);
			const verifyResponse = await nhost.auth.verifyElevateWebauthn({
				email: nhost.getUserSession()?.user?.email,
				credential
			});
			if (verifyResponse.body.session) nhost.sessionStorage.set(verifyResponse.body.session);
			else throw new Error("Failed to get elevated session");
		} catch (error) {
			console.error("Elevation error:", error);
			throw new Error("Could not elevate permissions");
		}
	}, [requiresElevation, nhost]);
	useEffect(() => {
		fetchSecurityKeys();
	}, [fetchSecurityKeys]);
	return {
		hasSecurityKeys,
		securityKeys,
		isElevated,
		isLoading,
		requiresElevation,
		checkElevation,
		refreshSecurityKeys: fetchSecurityKeys
	};
}

//#endregion
//#region src/hooks/useNhostAuthElevated.ts
function useNhostAuthElevated({ fn, onSuccess, onError }) {
	const { requiresElevation, checkElevation } = useNhostSecurity();
	const { callAsync, isLoading, isSuccess, error, nhost } = useShared({
		onSuccess,
		onError
	});
	return {
		callAsync: useCallback(async (...params) => {
			if (requiresElevation) await checkElevation();
			const method = nhost.auth[fn];
			return callAsync((...p) => method(...p), ...params);
		}, [
			callAsync,
			nhost,
			fn,
			requiresElevation,
			checkElevation
		]),
		isLoading,
		isSuccess,
		error
	};
}

//#endregion
//#region src/hooks/useNhostStorage.ts
function useNhostStorage({ fn, onSuccess, onError }) {
	const { callAsync, isLoading, isSuccess, error, nhost } = useShared({
		onSuccess,
		onError
	});
	return {
		callAsync: useCallback(async (...params) => {
			const method = nhost.storage[fn];
			return callAsync((...p) => method(...p), ...params);
		}, [
			nhost,
			fn,
			callAsync
		]),
		isLoading,
		isSuccess,
		error
	};
}

//#endregion
export { NhostContext, NhostProvider, useNhost, useNhostAuth, useNhostAuthElevated, useNhostSecurity, useNhostStorage };